  ('pen-compromise-rmo7-2015', 'penalty.compromise.failure_to_file_pay', 'penalty', 'all', '{"brackets":[{"over":"0","not_over":"500","amount":"200"},{"over":"500","not_over":"1000","amount":"400"},{"over":"1000","not_over":"2000","amount":"700"},{"over":"2000","not_over":"5000","amount":"1000"},{"over":"5000","not_over":"10000","amount":"1500"},{"over":"10000","not_over":"20000","amount":"3000"},{"over":"20000","not_over":"50000","amount":"5000"},{"over":"50000","not_over":"100000","amount":"10000"},{"over":"100000","not_over":"500000","amount":"20000"},{"over":"500000","not_over":"1000000","amount":"30000"},{"over":"1000000","not_over":"5000000","amount":"40000"},{"over":"5000000","not_over":null,"amount":"50000"}]}'::jsonb, '2015-01-01', null, 'RMO 7-2015, Annex A (schedule of compromise penalties, NIRC Sec. 255 violations)', 'https://www.bir.gov.ph/', null, true, 'LOW CONFIDENCE: bracket amounts and effectivity reconstructed from memory. Replace from the current RMO annex before launch.'),
